@Mod.EventBusSubscriber(modid="thaumcraft")
public final class TurretProbe {
 static final BlockPos P=new BlockPos(65008,160,8);
 static void check(boolean ok,String msg){if(!ok)throw new AssertionError(msg);}
 static CrossbowTurret turret(ServerLevel l,ServerPlayer p,boolean advanced){var t=new CrossbowTurret((advanced?TurretContent.ADVANCED:TurretContent.BASIC).get(),l);t.configure(p.getUUID(),2);t.setPos(Vec3.atBottomCenterOf(P));check(l.addFreshEntity(t),"Cannot spawn crossbow");return t;}
 static net.minecraft.nbt.CompoundTag snapshot(CrossbowTurret t){var out=TagValueOutput.createWithContext(ProblemReporter.DISCARDING,t.registryAccess());t.saveWithoutId(out);return out.buildResult();}
 static void resetFire(CrossbowTurret t){var data=snapshot(t);data.putLong("turret_fire_at",0);t.load(TagValueInput.create(ProblemReporter.DISCARDING,t.registryAccess(),data));}
 static List<AbstractArrow> arrows(ServerLevel l){return l.getEntitiesOfClass(AbstractArrow.class,new AABB(P).inflate(30));}
 static AbstractArrow shoot(ServerLevel l,CrossbowTurret t){resetFire(t);var before=new HashSet<>(arrows(l));t.tick();var created=arrows(l).stream().filter(a->!before.contains(a)).toList();check(created.size()==1,"Crossbow did not produce exactly one physical arrow");return created.getFirst();}
 static ItemStack tipped(){var s=new ItemStack(Items.TIPPED_ARROW,8);s.set(DataComponents.POTION_CONTENTS,new PotionContents(Potions.SLOWNESS));return s;}
 static void clean(ServerLevel l){for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++)l.getChunk((P.getX()>>4)+x,z);for(var q:BlockPos.betweenClosed(P.offset(-6,-2,-6),P.offset(6,5,16)))l.setBlockAndUpdate(q,q.getY()==P.getY()-1?Blocks.SMOOTH_STONE.defaultBlockState():Blocks.AIR.defaultBlockState());l.getEntitiesOfClass(Entity.class,new AABB(P).inflate(30),e->!(e instanceof net.minecraft.world.entity.player.Player)).forEach(Entity::discard);}
 static void run(ServerLevel l,ServerPlayer p){clean(l);p.setPos(Vec3.atBottomCenterOf(P.west(4)));GrappleProbe.knowledge(p);
  var zombie=new net.minecraft.world.entity.monster.zombie.Zombie(EntityTypes.ZOMBIE,l);zombie.setPos(Vec3.atBottomCenterOf(P.south(8)));zombie.setNoAi(true);zombie.setNoGravity(true);l.addFreshEntity(zombie);
  var basic=turret(l,p,false);basic.ammunition.setItem(0,new ItemStack(Items.ARROW,8));var arrow=shoot(l,basic);check(basic.ammunition.getItem(0).getCount()==7&&arrow.pickup==AbstractArrow.Pickup.DISALLOWED,"Arrow cost or pickup rule wrong");for(int i=0;i<20&&!arrow.isRemoved();i++)arrow.tick();check(zombie.getHealth()<zombie.getMaxHealth(),"Physical normal arrow did not hit enemy");basic.discard();arrows(l).forEach(Entity::discard);zombie.damageCooldownTime=0;zombie.setHealth(zombie.getMaxHealth());
  var t=turret(l,p,true);t.ammunition.setItem(0,tipped());arrow=shoot(l,t);check(arrow instanceof TurretArrow a&&a.getColor()!=-1,"Potion color/effects missing on native arrow");for(int i=0;i<24&&!arrow.isRemoved();i++)arrow.tick();check(zombie.hasEffect(net.minecraft.world.effect.MobEffects.SLOWNESS),"Tipped arrow did not apply potion; health="+zombie.getHealth()+" effects="+zombie.getActiveEffects()+" arrow="+arrow.position()+" removed="+arrow.isRemoved()+" target="+zombie.position());check(t.ammunition.getItem(0).getCount()==7,"Tipped arrow cost wrong");arrows(l).forEach(Entity::discard);zombie.damageCooldownTime=0;zombie.setHealth(zombie.getMaxHealth());
  t.ammunition.setItem(0,new ItemStack(Items.SPECTRAL_ARROW,4));arrow=shoot(l,t);check(arrow instanceof TurretSpectralArrow,"Spectral projectile missing");for(int i=0;i<24&&!arrow.isRemoved();i++)arrow.tick();check(zombie.hasEffect(net.minecraft.world.effect.MobEffects.GLOWING),"Spectral arrow did not apply glowing");arrows(l).forEach(Entity::discard);thaumcraft.Thaumcraft.LOGGER.info("TURRET67_AMMUNITION_OK: native normal, tipped and spectral impacts; exact cost, no pickup duplication");
  t.ammunition.setItem(0,tipped());t.targets(7);var saved=snapshot(t);var copy=new CrossbowTurret(TurretContent.ADVANCED.get(),l);copy.load(TagValueInput.create(ProblemReporter.DISCARDING,l.registryAccess(),saved));check(copy.owner().equals(p.getUUID())&&copy.targets()==7&&ItemStack.matches(copy.ammunition.getItem(0),tipped()),"Saved turret lost owner, flags or potion stack");var menu=new TurretMenu(77,p.getInventory(),t.ammunition,t);check(menu.clickMenuButton(p,0)&&t.targets()==6&&menu.clickMenuButton(p,0)&&t.targets()==7,"Independent target controls failed");var stranger=new ServerPlayer(l.getServer(),l,new GameProfile(UUID.randomUUID(),"OtherOwner"),ClientInformation.createDefault());stranger.setPos(p.position());check(!menu.stillValid(stranger)&&!menu.clickMenuButton(stranger,1),"Non-owner configured crossbow");check(!menu.slots.getFirst().mayPlace(new ItemStack(Items.STONE)),"Ammo slot accepted stone");check(t.eligible(p,zombie)&&!t.eligible(p,p),"Owner protection failed");var pet=new net.minecraft.world.entity.animal.wolf.Wolf(EntityTypes.WOLF,l);pet.setOwner(p);check(!t.eligible(p,pet),"Owner pet targeted");var cow=new net.minecraft.world.entity.animal.cow.Cow(EntityTypes.COW,l);check(t.eligible(p,cow),"Animal toggle ignored");t.targets(2);check(!t.eligible(p,cow),"Animal toggle failed to disable");
  l.setBlockAndUpdate(P.east(),Blocks.REDSTONE_BLOCK.defaultBlockState());int count=t.ammunition.getItem(0).getCount();resetFire(t);t.tick();check(count==t.ammunition.getItem(0).getCount()&&arrows(l).isEmpty(),"Powered crossbow fired");l.setBlockAndUpdate(P.east(),Blocks.AIR.defaultBlockState());for(int x=-4;x<=4;x++)for(int y=0;y<=4;y++)l.setBlockAndUpdate(P.offset(x,y,4),Blocks.STONE.defaultBlockState());resetFire(t);t.tick();check(count==t.ammunition.getItem(0).getCount()&&arrows(l).isEmpty(),"Crossbow fired through wall");for(int x=-4;x<=4;x++)for(int y=0;y<=4;y++)l.setBlockAndUpdate(P.offset(x,y,4),Blocks.AIR.defaultBlockState());l.players().remove(p);resetFire(t);t.tick();check(count==t.ammunition.getItem(0).getCount(),"Absent-owner turret fired");l.players().add(p);
  zombie.discard();t.ammunition.clearContent();l.setBlockAndUpdate(P.below(),Blocks.DISPENSER.defaultBlockState().setValue(DispenserBlock.FACING,Direction.UP));var dispenser=(DispenserBlockEntity)l.getBlockEntity(P.below());dispenser.setItem(0,new ItemStack(Items.STONE,3));dispenser.setItem(1,tipped());resetFire(t);t.tick();check(dispenser.getItem(1).isEmpty()&&dispenser.getItem(0).getCount()==3&&ItemStack.matches(t.ammunition.getItem(0),tipped()),"Dispenser lost or changed ammunition");t.tick();check(t.ammunition.getItem(0).getCount()==8,"Dispenser duplicated loaded stack");
  thaumcraft.Thaumcraft.LOGGER.info("TURRET67_OWNER_RELOAD_SAVE_OK: exact potion snapshot, owner-only menu, target flags, pets, redstone, obstruction, offline owner, dispenser transfer");t.discard();l.setBlockAndUpdate(P,ThaumaturgyContent.TURRET_ADVANCED.get().defaultBlockState());var legacy=(TurretEntity)l.getBlockEntity(P);legacy.claim(p);legacy.interact(p,new ItemStack(Items.ARROW,19));legacy.interact(p,new ItemStack(Items.STICK));legacy.serverTick();var migrated=l.getEntitiesOfClass(CrossbowTurret.class,new AABB(P).inflate(1));check(l.getBlockState(P).isAir()&&migrated.size()==1&&migrated.getFirst().owner().equals(p.getUUID())&&migrated.getFirst().ammunition.getItem(0).getCount()==19&&migrated.getFirst().targets()==3,"Legacy block migration lost content");check(ThaumaturgyContent.TURRET.get().asItem()==thaumcraft.content.SimpleContent.ITEMS.get("turret_basic").get(),"Legacy block item/infusion identity changed");migrated.forEach(Entity::discard);
  var stack=new ItemStack(thaumcraft.content.SimpleContent.ITEMS.get("turret_basic").get(),1);p.setItemInHand(InteractionHand.MAIN_HAND,stack);var hit=new BlockHitResult(Vec3.atCenterOf(P.below()),Direction.UP,P.below(),false);check(stack.useOn(new net.minecraft.world.item.context.UseOnContext(p,InteractionHand.MAIN_HAND,hit))==InteractionResult.SUCCESS&&stack.isEmpty(),"Native placement failed");var placed=l.getEntitiesOfClass(CrossbowTurret.class,new AABB(P).inflate(1)).getFirst();placed.ammunition.setItem(0,tipped());p.setShiftKeyDown(true);placed.interact(p,InteractionHand.OFF_HAND,Vec3.ZERO);p.setShiftKeyDown(false);check(placed.isRemoved(),"Owner dismantle did not remove crossbow");var drops=l.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(P).inflate(3));check(drops.stream().anyMatch(e->ItemStack.matches(e.getItem(),tipped()))&&drops.stream().filter(e->e.getItem().is(thaumcraft.content.SimpleContent.ITEMS.get("turret_basic").get())).mapToInt(e->e.getItem().getCount()).sum()==1,"Dismantle lost ammo or duplicated turret");thaumcraft.Thaumcraft.LOGGER.info("TURRET67_MIGRATION_PLACE_OK: legacy owner/ammo/mode, stable item IDs, native placement and exact dismantle drops");
 }
 @SubscribeEvent public static void start(ServerStartedEvent e){if(!System.getProperty("thaumcraft.bookProbe","").equals("turret"))return;var l=e.getServer().overworld();e.getServer().tickRateManager().setFrozen(true);var p=new ServerPlayer(e.getServer(),l,new GameProfile(UUID.randomUUID(),"TurretProof"),ClientInformation.createDefault()){@Override public void sendSystemMessage(net.minecraft.network.chat.Component c,boolean overlay){}@Override protected ItemCooldowns createItemCooldowns(){return new ItemCooldowns();}};new net.minecraft.server.network.ServerGamePacketListenerImpl(e.getServer(),new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),p,net.minecraft.server.network.CommonListenerCookie.createInitial(p.getGameProfile(),false)){@Override public void send(net.minecraft.network.protocol.Packet<?> packet){}@Override public void send(net.minecraft.network.protocol.Packet<?> packet,io.netty.channel.ChannelFutureListener listener){}};p.gameMode.changeGameModeForPlayer(GameType.SURVIVAL);l.players().add(p);try{run(l,p);}finally{l.players().remove(p);}thaumcraft.Thaumcraft.LOGGER.info("TURRET67_NATIVE_OK");e.getServer().halt(false);}
}
